    Returns:
        float: Розмір періодичного платежу.

    Raises:
        ValueError: Якщо вхідні аргументи порушують обмеження.
        TypeError: Якщо типи аргументів не відповідають очікуваним.
    """
    if not isinstance(principal, (int, float)) or isinstance(principal, bool):
        raise TypeError("Principal must be a float or int.")
    if not isinstance(annual_rate, (int, float)) or isinstance(annual_rate, bool):
        raise TypeError("Annual rate must be a float or int.")
    if not isinstance(years, int) or isinstance(years, bool):
        raise TypeError("Years must be an integer.")
    if not isinstance(periods_per_year, int) or isinstance(periods_per_year, bool):
        raise TypeError("Periods per year must be an integer.")

    if principal <= 0:
        raise ValueError("Principal must be greater than 0.")
    if annual_rate < 0:
        raise ValueError("Annual rate cannot be negative.")
    if years <= 0:
        raise ValueError("Years must be a positive integer.")
    if periods_per_year <= 0:
        raise ValueError("Periods per year must be a positive integer.")

